-- Every fixture rolls back through the deliberate WORKSPACE_RESULT exception.
DO $$
DECLARE u uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); o uuid; other_org uuid; w uuid; w2 uuid; other_ws uuid; ap uuid; c uuid; r uuid; n int; p int:=0; path text;
BEGIN
 INSERT INTO auth.users(id,email,aud,role,instance_id) VALUES(u,'ws-owner@test.local','authenticated','authenticated','00000000-0000-0000-0000-000000000000'),(m,'ws-admin@test.local','authenticated','authenticated','00000000-0000-0000-0000-000000000000'),(outsider,'ws-outside@test.local','authenticated','authenticated','00000000-0000-0000-0000-000000000000');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true); EXECUTE 'set local role authenticated';
 o:=public.create_organization('Workspace authorization test','Allowed'); SELECT id INTO w FROM public.workspaces WHERE org_id=o;
 IF public.has_workspace_role(w,'owner') THEN p:=p+1; ELSE RAISE EXCEPTION 'owner access'; END IF;
 BEGIN PERFORM public.create_workspace(o,'Quota bypass'); RAISE EXCEPTION 'trial workspace limit bypassed'; EXCEPTION WHEN OTHERS THEN IF sqlerrm='Your workspace limit has been reached' THEN p:=p+1; ELSE RAISE; END IF; END;
 EXECUTE 'reset role'; INSERT INTO public.workspaces(org_id,name) VALUES(o,'Restricted') RETURNING id INTO w2;
 INSERT INTO public.organization_members(org_id,user_id,role) VALUES(o,m,'admin');
 INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(w,m,'member');
 INSERT INTO public.business_facts(org_id,workspace_id,key,value,source_type) VALUES(o,w2,'secret','restricted','user');
 INSERT INTO public.documents(org_id,workspace_id,name,storage_path,mime,size_bytes,uploaded_by) VALUES(o,w2,'private.txt',o::text||'/'||w2::text||'/private.txt','text/plain',5,u);
 INSERT INTO public.conversations(org_id,workspace_id,user_id,title) VALUES(o,w2,m,'Revoked history') RETURNING id INTO c;
 INSERT INTO public.messages(org_id,conversation_id,role,content) VALUES(o,c,'user','secret memory');
 INSERT INTO public.agent_runs(org_id,workspace_id,agent_key,user_id) VALUES(o,w2,'growth_officer',m) RETURNING id INTO r;
 INSERT INTO public.approvals(org_id,workspace_id,title,capability_key,requested_by) VALUES(o,w2,'Private approval','strategy.recommend',u) RETURNING id INTO ap;
 path:=o::text||'/'||w2::text||'/private.txt';
 INSERT INTO storage.objects(bucket_id,name,owner) VALUES('documents',path,u);
 PERFORM set_config('request.jwt.claims',json_build_object('sub',m,'role','authenticated')::text,true); EXECUTE 'set local role authenticated';
 IF public.has_workspace_role(w,'member') AND NOT public.has_workspace_role(w,'admin') THEN p:=p+1; ELSE RAISE EXCEPTION 'workspace role cap'; END IF;
 IF NOT public.has_workspace_role(w2,'viewer') THEN p:=p+1; ELSE RAISE EXCEPTION 'implicit admin access'; END IF;
 SELECT count(*) INTO n FROM public.workspaces WHERE id=w2; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'workspace read'; END IF;
 SELECT count(*) INTO n FROM public.business_facts WHERE workspace_id=w2; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'fact read'; END IF;
 SELECT count(*) INTO n FROM public.documents WHERE workspace_id=w2; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'document read'; END IF;
 SELECT count(*) INTO n FROM public.conversations WHERE id=c; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'historical conversation read'; END IF;
 SELECT count(*) INTO n FROM public.messages WHERE conversation_id=c; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'historical message read'; END IF;
 SELECT count(*) INTO n FROM public.agent_runs WHERE id=r; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'run read'; END IF;
 SELECT count(*) INTO n FROM public.approvals WHERE id=ap; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'approval read'; END IF;
 SELECT count(*) INTO n FROM storage.objects WHERE name=path AND bucket_id='documents'; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'storage read'; END IF;
 UPDATE public.business_facts SET value='attack' WHERE workspace_id=w2; GET DIAGNOSTICS n=ROW_COUNT; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'fact update'; END IF;
 DELETE FROM public.documents WHERE workspace_id=w2; GET DIAGNOSTICS n=ROW_COUNT; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'document delete'; END IF;
 IF NOT public.document_path_access(path,'admin') THEN p:=p+1; ELSE RAISE EXCEPTION 'storage delete authorization'; END IF;
 BEGIN INSERT INTO public.business_facts(org_id,workspace_id,key,value,source_type) VALUES(o,w2,'attack','attack','user'); RAISE EXCEPTION 'fact insert accepted'; EXCEPTION WHEN insufficient_privilege THEN p:=p+1; END;
 BEGIN INSERT INTO storage.objects(bucket_id,name,owner) VALUES('documents',o::text||'/'||w2::text||'/attack.txt',m); RAISE EXCEPTION 'storage insert accepted'; EXCEPTION WHEN insufficient_privilege THEN p:=p+1; END;
 BEGIN PERFORM public.confirm_business_profile(w2,'{}','[{"key":"attack","value":"attack","source_type":"user","confidence":1}]'); RAISE EXCEPTION 'confirmation accepted'; EXCEPTION WHEN OTHERS THEN IF sqlerrm='forbidden' THEN p:=p+1; ELSE RAISE; END IF; END;
 BEGIN PERFORM public.decide_approval(ap,true,'attack'); RAISE EXCEPTION 'approval accepted'; EXCEPTION WHEN OTHERS THEN IF sqlerrm='forbidden' THEN p:=p+1; ELSE RAISE; END IF; END;
 BEGIN PERFORM public.set_workspace_member(w2,m,'admin'); RAISE EXCEPTION 'self assignment accepted'; EXCEPTION WHEN OTHERS THEN IF sqlerrm='Only organization owners can assign workspace access' THEN p:=p+1; ELSE RAISE; END IF; END;
 BEGIN INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(w2,m,'admin'); RAISE EXCEPTION 'direct assignment accepted'; EXCEPTION WHEN insufficient_privilege THEN p:=p+1; END;
 IF NOT public.has_platform_role('platform_owner') THEN p:=p+1; ELSE RAISE EXCEPTION 'platform escalation'; END IF;
 IF NOT public.document_path_access('malformed','viewer') THEN p:=p+1; ELSE RAISE EXCEPTION 'malformed storage path'; END IF;
 EXECUTE 'reset role'; PERFORM set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true); EXECUTE 'set local role authenticated';
 PERFORM public.set_workspace_member(w2,m,'viewer'); p:=p+1;
 EXECUTE 'reset role'; PERFORM set_config('request.jwt.claims',json_build_object('sub',m,'role','authenticated')::text,true); EXECUTE 'set local role authenticated';
 IF public.has_workspace_role(w2,'viewer') AND NOT public.has_workspace_role(w2,'member') THEN p:=p+1; ELSE RAISE EXCEPTION 'viewer grant'; END IF;
 SELECT count(*) INTO n FROM storage.objects WHERE name=path AND bucket_id='documents'; IF n=1 THEN p:=p+1; ELSE RAISE EXCEPTION 'authorized storage read'; END IF;
 BEGIN INSERT INTO public.business_facts(org_id,workspace_id,key,value,source_type) VALUES(o,w2,'viewer','attack','user'); RAISE EXCEPTION 'viewer write accepted'; EXCEPTION WHEN insufficient_privilege THEN p:=p+1; END;
 EXECUTE 'reset role'; PERFORM set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true); EXECUTE 'set local role authenticated';
 PERFORM public.set_workspace_member(w2,m,NULL); EXECUTE 'reset role'; PERFORM set_config('request.jwt.claims',json_build_object('sub',m,'role','authenticated')::text,true); EXECUTE 'set local role authenticated';
 IF NOT public.has_workspace_role(w2,'viewer') THEN p:=p+1; ELSE RAISE EXCEPTION 'revocation'; END IF;
 EXECUTE 'reset role'; DELETE FROM public.organization_members WHERE org_id=o AND user_id=m;
 SELECT count(*) INTO n FROM public.workspace_members WHERE user_id=m AND workspace_id=w; IF n=0 THEN p:=p+1; ELSE RAISE EXCEPTION 'removed member assignments retained'; END IF;
 INSERT INTO public.organization_members(org_id,user_id,role) VALUES(o,m,'admin');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',m,'role','authenticated')::text,true); EXECUTE 'set local role authenticated';
 IF NOT public.has_workspace_role(w,'viewer') THEN p:=p+1; ELSE RAISE EXCEPTION 'rejoin restored stale access'; END IF;
 EXECUTE 'reset role'; RAISE EXCEPTION 'WORKSPACE_RESULT pass=% fail=0',p;
END $$;